// Thread is the resolver for the thread field.
func (r *queryResolver) Thread(ctx context.Context, id string) (*domain.Thread, error) {
	start := perf.Now()
	defer func() {
		metrics.RequestDuration.WithLabelValues("graphql_thread").Observe(perf.Since(start).Seconds())
	}()

	// Get user info from context
	_, companyID, _, err := getUserInfoFromContext(ctx)
	if err != nil {
		metrics.RequestsTotal.WithLabelValues("graphql_thread", "error").Inc()
		return nil, fmt.Errorf("authentication required: %w", err)
	}

	thread, err := r.threadRepo.GetThreadWithPermissionCheck(ctx, id, companyID)
	if err != nil {
		metrics.RequestsTotal.WithLabelValues("graphql_thread", "error").Inc()
		// Return user-friendly error for access denied
		if errors.Is(err, shderrors.ErrAccessDenied) {
			return nil, fmt.Errorf("access denied: you don't have permission to view this thread")
		}
		// Return not found errors as-is
		if apperrors.IsNotFound(err) {
			return nil, err
		}
		// Return other errors as-is (database errors, connection errors, etc.)
		return nil, fmt.Errorf("failed to get thread: %w", err)
	}

	// Batch load refs if requested in selections
	if err := r.BatchLoadThreadData(ctx, []*domain.Thread{thread}); err != nil {
		return nil, err
	}

	// Cache the access check result for child resolvers (steps, validationResults, etc.)
	ctx = cacheAccessCheck(ctx, thread.ID, true)
	metrics.RequestsTotal.WithLabelValues("graphql_thread", "success").Inc()
	return thread, nil
}

// Threads is the resolver for the threads field.
func (r *queryResolver) Threads(ctx context.Context, actor *string, contractName *string, contractVersion *int, status *string, tags []string, startedAfter *string, startedBefore *string, completedAfter *string, completedBefore *string, limit *int, offset *int) (*domain.ThreadConnection, error) {
	resolverStart := perf.Now()
	perf.Log("\n[PERF] ========== Threads() Resolver START ==========\n")
	defer func() {
		perf.Log("[PERF] ========== Threads() Resolver TOTAL: %v ==========\n\n", perf.Since(resolverStart))
		metrics.RequestDuration.WithLabelValues("graphql_threads").Observe(perf.Since(resolverStart).Seconds())
	}()

	// Get user info from context (companyID for security)
	authStart := perf.Now()
	ownerID, companyID, _, err := getUserInfoFromContext(ctx)
	perf.Log("[PERF] Threads.getUserInfo: %v\n", perf.Since(authStart))
	if err != nil {
		return nil, fmt.Errorf("authentication required: %w", err)
	}

	// Normalize pagination using helper
	limitVal, offsetVal := NormalizePagination(&ThreadQueryOptions{Limit: limit, Offset: offset})

	// Get postgres repository
	postgresRepo := r.threadRepo.GetPostgresRepo()
	if postgresRepo == nil {
		return nil, apperrors.NewInternalError("Postgres repository not available", nil)
	}

	// Query threads with SQL-based access filtering (includes archived data)
	queryStart := perf.Now()
	threads, totalCount, err := postgresRepo.QueryThreadsWithAccess(ctx, companyID, ownerID, actor, contractName, contractVersion, status, tags, startedAfter, startedBefore, completedAfter, completedBefore, limitVal, offsetVal)
	perf.Log("[PERF] Threads.QueryThreadsWithAccess: %v (returned %d threads, total: %d)\n", perf.Since(queryStart), len(threads), totalCount)

	if err != nil {
		r.logger.Error("failed to query threads",
			zap.String("company_id", companyID),
			zap.String("owner_id", ownerID),
			zap.Error(err),
		)
		return nil, apperrors.NewInternalError("Failed to query threads with access", err)
	}

	// Batch load refs (no access filtering needed - already done in SQL)
	if len(threads) > 0 {
		if err := r.BatchLoadThreadData(ctx, threads); err != nil {
			return nil, err
		}
	}

	return &domain.ThreadConnection{
		Threads:    threads,
		TotalCount: totalCount,
	}, nil
}

