// VerifyThreadIntegrity is the resolver for the verifyThreadIntegrity query
// Verifies the hash chain integrity of a thread (separate from thread query for performance)
func (r *queryResolver) VerifyThreadIntegrity(ctx context.Context, threadID string) (*domain.HashChainStatus, error) {
	// Call the activity repository to verify the chain
	status, err := r.activityRepo.VerifyActivityChain(ctx, threadID)
	if err != nil {
		r.logger.Error("failed to verify thread integrity",
			zap.String("thread_id", threadID),
			zap.Error(err),
		)
		return nil, fmt.Errorf("failed to verify thread integrity: %w", err)
	}
	return status, nil
}

// Verifies the hash integrity of a single step
func (r *queryResolver) VerifyStepIntegrity(ctx context.Context, threadID string, stepName string, idempotencyKey string) (*domain.StepIntegrityStatus, error) {
	// Get the step hashes
	hash, prevHash, err := r.activityRepo.GetStepHashes(ctx, threadID, stepName, idempotencyKey)
	if err != nil {
		r.logger.Error("failed to get step hashes",
			zap.String("thread_id", threadID),
			zap.String("step_name", stepName),
			zap.Error(err),
		)
		return nil, fmt.Errorf("failed to get step hashes: %w", err)
	}

	// Verify the step hash
	verified, errMsg, err := r.activityRepo.VerifyStepHash(ctx, threadID, stepName, idempotencyKey)
	if err != nil {
		r.logger.Error("failed to verify step hash",
			zap.String("thread_id", threadID),
			zap.String("step_name", stepName),
			zap.Error(err),
		)
		return nil, fmt.Errorf("failed to verify step hash: %w", err)
	}

	status := &domain.StepIntegrityStatus{
		Verified: verified,
		Hash:     hash,
		PrevHash: prevHash,
	}

	if errMsg != "" {
		status.Error = &errMsg
	}

	return status, nil
}

// CheckCredits is the resolver for the checkCredits field.
func (r *queryResolver) CheckCredits(ctx context.Context, meter *string, amount *int) (bool, error) {
	_, companyID, _, err := getUserInfoFromContext(ctx)
	if err != nil {
		return false, fmt.Errorf("authentication required: %w", err)
	}

	meterVal := ""
	if meter != nil {
		meterVal = *meter
	}

	amountVal := int64(0)
	if amount != nil {
		amountVal = int64(*amount)
	}

	if err := r.planService.CheckCreditAvailable(ctx, companyID, meterVal, amountVal); err != nil {
		if errors.Is(err, service.ErrInsufficientCredit) || errors.Is(err, service.ErrNoAccount) {
			return false, nil
		}
		return false, fmt.Errorf("failed to check credits: %w", err)
	}

	return true, nil
}

// EntityProfile is the resolver for the entityProfile field.
func (r *queryResolver) EntityProfile(ctx context.Context, id *string, refKey *string, typeArg *string) (*generated.EntityProfile, error) {
	_, companyID, _, err := getUserInfoFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %w", err)
	}

	if id != nil && *id != "" {
		profile, err := r.entityProfileRepo.GetProfileByID(ctx, companyID, *id)
		if err != nil || profile == nil {
			return nil, nil // Not found or error
		}
		// Fetch profile type details
		pType, err := r.entityProfileTypeRepo.GetProfileTypeByID(ctx, profile.ProfileTypeID)
		if err != nil {
			return nil, fmt.Errorf("failed to get profile type: %w", err)
		}

		return &generated.EntityProfile{
			ID:            profile.ID,
			RefKey:        profile.RefKey,
			CompanyID:     profile.CompanyID,
			ProfileTypeID: profile.ProfileTypeID,
			ProfileType:   toGraphQLProfileType(pType),
			Name:          &profile.Name,
			CreatedAt:     profile.CreatedAt.Format(time.RFC3339),
			LastActiveAt:  profile.LastActiveAt.Format(time.RFC3339),
		}, nil
	}

	if refKey != nil && typeArg != nil && *refKey != "" && *typeArg != "" {
		profile, err := r.entityProfileRepo.GetProfileByTypeName(ctx, companyID, slug.ToSlug(*typeArg), *refKey)
		if err != nil || profile == nil {
			return nil, nil
		}
		// Fetch profile type details
		pType, err := r.entityProfileTypeRepo.GetProfileTypeByID(ctx, profile.ProfileTypeID)
		if err != nil {
			r.logger.Warn("could not fetch profile type details",
				zap.String("profile_id", profile.ID),
				zap.String("type", *typeArg),
				zap.Error(err),
			)
			return &generated.EntityProfile{
				ID:            profile.ID,
				RefKey:        profile.RefKey,
				CompanyID:     profile.CompanyID,
				ProfileTypeID: profile.ProfileTypeID,
				ProfileType:   nil,
				Name:          &profile.Name,
				CreatedAt:     profile.CreatedAt.Format(time.RFC3339),
				LastActiveAt:  profile.LastActiveAt.Format(time.RFC3339),
			}, nil
		}

		return &generated.EntityProfile{
			ID:            profile.ID,
			RefKey:        profile.RefKey,
			CompanyID:     profile.CompanyID,
			ProfileTypeID: profile.ProfileTypeID,
			ProfileType:   toGraphQLProfileType(pType),
			Name:          &profile.Name,
			CreatedAt:     profile.CreatedAt.Format(time.RFC3339),
			LastActiveAt:  profile.LastActiveAt.Format(time.RFC3339),
		}, nil
	}

	return nil, fmt.Errorf("must provide either id or both refKey and type")
}

