// EntityProfilesByType is the resolver for the entityProfilesByType field.
func (r *queryResolver) EntityProfilesByType(ctx context.Context, typeArg string, search *string, limit *int, offset *int) (*generated.EntityProfileConnection, error) {
	_, companyID, _, err := getUserInfoFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %w", err)
	}

	limitVal := 20
	if limit != nil {
		limitVal = *limit
	}
	offsetVal := 0
	if offset != nil {
		offsetVal = *offset
	}
	searchVal := ""
	if search != nil {
		searchVal = *search
	}

	items, total, err := r.entityProfileRepo.ListProfilesByType(ctx, companyID, slug.ToSlug(typeArg), searchVal, limitVal, offsetVal)
	if err != nil {
		r.logger.Error("failed to list entity profiles by type",
			zap.String("company_id", companyID),
			zap.String("type", typeArg),
			zap.Error(err),
		)
		return nil, apperrors.NewInternalError("Failed to list entity profiles", err)
	}

	pt, err := r.entityProfileTypeRepo.GetProfileTypeByType(ctx, companyID, slug.ToSlug(typeArg))
	if err != nil {
		r.logger.Warn("could not fetch profile type details for connection",
			zap.String("company_id", companyID),
			zap.String("type", typeArg),
			zap.Error(err),
		)
	}

	var graphqlPt *generated.EntityProfileType
	if pt != nil {
		graphqlPt = toGraphQLProfileType(pt)
	}

	out := make([]*generated.EntityProfile, 0, len(items))
	for _, p := range items {
		if p == nil {
			continue
		}
		name := p.Name
		out = append(out, &generated.EntityProfile{
			ID:            p.ID,
			RefKey:        p.RefKey,
			CompanyID:     p.CompanyID,
			ProfileTypeID: p.ProfileTypeID,
			ProfileType:   graphqlPt,
			Name:          &name,
			CreatedAt:     p.CreatedAt.Format(time.RFC3339),
			LastActiveAt:  p.LastActiveAt.Format(time.RFC3339),
		})
	}

	return &generated.EntityProfileConnection{
		Items:       out,
		TotalCount:  total,
		ProfileType: graphqlPt,
	}, nil
}

// ContractViolations is the resolver for the contractViolations field.
func (r *queryResolver) ContractViolations(ctx context.Context, contractName *string, refKey *string, refValue *string, severity []string, startedAfter *string, startedBefore *string, limit *int, offset *int) ([]*domain.ThreadNotification, error) {
	_, companyID, _, err := getUserInfoFromContext(ctx)
	if err != nil {
		return nil, fmt.Errorf("authentication required: %w", err)
	}

	limitVal := 50
	if limit != nil && *limit > 0 {
		limitVal = *limit
	}
	offsetVal := 0
	if offset != nil && *offset > 0 {
		offsetVal = *offset
	}

	postgresRepo := r.threadRepo.GetPostgresRepo()
	if postgresRepo == nil {
		return nil, apperrors.NewInternalError("Postgres repository not available", nil)
	}

	notifRepo := postgres.NewThreadNotificationRepository(postgresRepo.GetPool())

	notifications, err := notifRepo.GetGlobalNotifications(
		ctx,
		companyID,
		contractName,
		refKey,
		refValue,
		severity,
		startedAfter,
		startedBefore,
		limitVal,
		offsetVal,
	)
	if err != nil {
		r.logger.Error("failed to get contract violations",
			zap.String("company_id", companyID),
			zap.Error(err),
		)
		return nil, fmt.Errorf("failed to fetch contract violations: %w", err)
	}

	return notifications, nil
}

// Error is the resolver for the error field on StepHistory.
// Extracts error message from metadata JSON when status is "failed" or "error".
// Only reads from metadata field (SDK-controlled), not context (customer data).
func (r *stepHistoryResolver) Error(ctx context.Context, obj *domain.StepHistory) (*string, error) {
	// Only extract error for failed/error statuses
	if obj.Status != "failed" && obj.Status != "error" {
		return nil, nil
	}

	// Extract from metadata field (SDK stores error here)
	// We don't read from context as that contains customer data
	if obj.Metadata == "" {
		return nil, nil
	}

	var metadataData map[string]interface{}
	if err := json.Unmarshal([]byte(obj.Metadata), &metadataData); err != nil {
		return nil, nil
	}

	errorVal, ok := metadataData["error"]
	if !ok {
		return nil, nil
	}

	// Convert error value to string
	switch v := errorVal.(type) {
	case string:
		return &v, nil
	case map[string]interface{}:
		// If error is an object, stringify it
		errorJSON, err := json.Marshal(v)
		if err != nil {
			return nil, nil
		}
		errorStr := string(errorJSON)
		return &errorStr, nil
	default:
		// For other types, convert to string
		errorStr := fmt.Sprintf("%v", v)
		return &errorStr, nil
	}
}

